for (const [id,b] of Object.entries(became)) {
  const was = base.entries.find(e=>e.id===id);
  const now = live.entries.find(e=>e.id===id);
  assert.ok(was && now,id);
  now.buying_tips = [was.buying_tips[0],b.tip1,...was.buying_tips.slice(1)];
  for (const f of ['decision','cart_pick','tier_note']) if(b[f]) now[f]=b[f];
  if(b.watch_add) now.watch_out = [...(was.watch_out ?? []),b.watch_add];
  if(b.glossed) now.detail = "'`${was.detail} ${was.tier_note}`;
  if(b.science) {
    const oldSentence='"'A gum on the list is a texture choice by the maker, never a ranking.';
    const newSentence='A gum on the list is a texture choice by the maker.';
    const science=JSON.stringify(was.science);
    assert.equal(science.split(oldSentence).length,2);
    now.science=JSON.parse(science.replace(oldSentence,newSentence));
  }
  changedFields.set(id,Object.keys(now).filter(f=>JSON.stringify(now[f])"'!==JSON.stringify(was[f])));
}
const reviewPath='"'docs/do-lines-review.md';
const oldReview=git(reviewPath);
assert.equal(readFileSync(reviewPath,'utf8'),oldReview);
const seen=new Set();
const review=oldReview.split('\\n').map(line=>{
  if("'!line.startsWith('"'| "'`'"')) return line;
  const id=line.split('"'`'"')[1];
  if("'!became[id]?.decision || seen.has(id)) return line;
  const cells=line.split('"'|');
  assert.equal(cells[3].trim(),base.entries.find(e=>e.id===id).decision,id);
  cells[3]=' '+became[id].decision+' ';
  seen.add(id);
  return cells.join('|');
}).join('\\n');
assert.equal(seen.size,20);
const pinsPath='server/test/acceptance/twoLinePin.js';
const oldPins=readFileSync(pinsPath,'utf8');
const pinJson=oldPins.match(/export const TWO_LINE = (\\{[\\s\\S]*?\\n\\});/)[1];
const pins=JSON.parse(pinJson);
assert.equal(JSON.stringify(pins,null,2),pinJson,'pin serialization');
let fields=0;
for(const [id,changed] of changedFields) {
  for(const f of changed) if(Object.hasOwn(pins[id],f)) {
    pins[id][f]=live.entries.find(e=>e.id===id)[f];
    fields++;
  }
}
const ids=Object.keys(became).map(id=>"'`'"'"'${id}'"'"'`).join('"', ');
const overlay="'`'"\\n// clean-pick-3 (2026-10-20) moved these dairy, plant-milk, meat, seafood and frozen fronts on; older batch tests read them as of 2ab7f2f, and cleanPick3.test.js owns the new text.\\nexport const CLEAN_PICK_3 = new Set(["'${ids}]);'"\\nconst PRE_CP3 = JSON.parse(execFileSync('git', ['show', '2ab7f2f:server/kristy_perimeter_kb.json'], { cwd: ROOT, maxBuffer: 64 << 20 }).toString());\\nexport const preCleanPick3 = (e) => (e && CLEAN_PICK_3.has(e.id) ? PRE_CP3.entries.find((x) => x.id === e.id) : e);\\n"'`;
assert.ok(!oldPins.includes('"'PRE_CP3'));
const newPins=oldPins.replace(pinJson,JSON.stringify(pins,null,2))+overlay;
